// Auto-generated image data - LushAura
const IMAGE_DATA = {
  'hero-main': 'data:image/png;base64,',
  'product-1': 'data:image/png;base64,',
  'product-2': 'data:image/png;base64,',
  'product-3': 'data:image/png;base64,',
  'product-4': 'data:image/png;base64,',
  'product-5': 'data:image/png;base64,',
  'product-6': 'data:image/png;base64,',
  'product-7': 'data:image/png;base64,',
  'product-8': 'data:image/png;base64,',
  'product-9': 'data:image/png;base64,',
};

// Replace all img src with base64 data on page load
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('img').forEach(img => {
    const src = img.getAttribute('src');
    if (src) {
      for (const [key, data] of Object.entries(IMAGE_DATA)) {
        if (src.includes(key)) {
          img.src = data;
          break;
        }
      }
    }
  });
});